documents.spec:
yamaa: "1.0"
type: spec
domain: ADSL
base: DM
keys: [USUBJID]
input:
  DM: {path: dm.csv}
output: {path: out.csv, columns: [USUBJID, BRTHDT, NAME]}
columns:
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: BRTHDT, type: date, derivation: {to_date: {source: DM.BRTHDTC}}}
  - {name: NAME, type: str, derivation: {first_available: {sources: [DM.NICK, DM.USUBJID]}}}
